words AS (
  SELECT packs.pack_code, unnest(packs.words) AS word
  FROM packs
)
INSERT INTO content_items (id, pack_id, value, normalized_value, aliases, active)
SELECT
  md5(p.id::text || ':' || words.word)::uuid,
  p.id,
  words.word,
  lower(regexp_replace(words.word, '[[:space:][:punct:]]', '', 'g')),
  '[]'::jsonb,
  TRUE
FROM words
JOIN content_packs p ON p.code = words.pack_code;
